&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;singleLevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Je richt &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;governance&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt; en beveiliging voor AI in: Data &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Loss&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt; Prevention-&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;policies&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;, tenant- en environment-instellingen voor &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Copilot&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt; Studio, en monitoring/&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;observability&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt; van agentgedrag.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;singleLevel&amp;quot;}&quot; data-aria-posinset=&quot;5&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Je beoordeelt en valideert AI-gegenereerde oplossingsontwerpen en -code op kwaliteit, security, kosten en schaalbaarheid, en stuurt bij waar nodig.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
