&lt;p&gt;&lt;br&gt;&lt;span data-contrast=&quot;none&quot;&gt;Apply with CV, transcripts, and references. If you have built something, include the link.&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Let’s see if you are the one.&lt;/span&gt;&lt;/strong&gt; &lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p style=&quot;line-height: 1.5;&quot;&gt;&lt;span style=&quot;font-family: &#39;trebuchet ms&#39;, geneva, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;Equal Opportunities for all (f/m/d)&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1.5;&quot;&gt;&lt;span style=&quot;font-family: &#39;trebuchet ms&#39;, geneva, sans-serif; font-size: 12pt;&quot;&gt;ALAIKA is an equal-opportunity employer. We hire on merit and welcome applications from people of all genders, backgrounds, ages, and identities.&amp;nbsp;Our team spirit celebrates diversity. We want you to be your true “you” and offer everyone an open culture and safe space&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;Find more English Speaking Jobs in Germany on Arbeitnow

&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Advise. Invest. Build.&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;Meet ALAIKA — a new kind of Financial Services firm — globally scaling,&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;headquartered&amp;nbsp;in&amp;nbsp;Munich.&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;The work is hard.&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;The bar is high.&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;P&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;artner&amp;nbsp;in 4-5&amp;nbsp;years possible&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;, for the ones who can keep up&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;a&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;n&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;d&amp;nbsp;actually build&amp;nbsp;a&amp;nbsp;business themselves&amp;nbsp;on our platform.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:160,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Stop reading if any of these describe you:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:160,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Aptos&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:220,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Specialisation.&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;You are a generalist with shallow&amp;nbsp;expertise&amp;nbsp;and a thin network&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;→&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;AI will eat your lunch. We bet on depth.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:160,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Aptos&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:220,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Ownership.&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;You spot the problem and walk it to your boss&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;→&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;We fall in love with problems.&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;Own&amp;nbsp;them.&amp;nbsp;Solve&amp;nbsp;them. Ship&amp;nbsp;solutions.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:160,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
