&lt;ul data-start=&quot;721&quot; data-end=&quot;1606&quot;&gt;
&lt;li style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot; data-start=&quot;721&quot; data-end=&quot;833&quot;&gt;
&lt;p data-start=&quot;723&quot; data-end=&quot;833&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;Lead and provide statistical support for clinical studies.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot; data-start=&quot;834&quot; data-end=&quot;940&quot;&gt;
&lt;p data-start=&quot;836&quot; data-end=&quot;940&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;Act as the&amp;nbsp;&lt;strong data-start=&quot;847&quot; data-end=&quot;868&quot;&gt;lead statistician&lt;/strong&gt;&amp;nbsp;on assigned studies, overseeing statistical strategy and deliverables&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot; data-start=&quot;941&quot; data-end=&quot;1136&quot;&gt;
&lt;p data-start=&quot;943&quot; data-end=&quot;998&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;Author and review key statistical documents, including:&lt;/span&gt;&lt;/p&gt;
&lt;ul data-start=&quot;1001&quot; data-end=&quot;1136&quot;&gt;
&lt;li style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot; data-start=&quot;1001&quot; data-end=&quot;1038&quot;&gt;
&lt;p data-start=&quot;1003&quot; data-end=&quot;1038&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;Statistical Analysis Plans (SAPs)&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot; data-start=&quot;1041&quot; data-end=&quot;1083&quot;&gt;
&lt;p data-start=&quot;1043&quot; data-end=&quot;1083&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;Analysis Database Specifications (ADS)&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot; data-start=&quot;1086&quot; data-end=&quot;1136&quot;&gt;
&lt;p data-start=&quot;1088&quot; data-end=&quot;1136&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;Statistical sections of clinical study reports&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot; data-start=&quot;1137&quot; data-end=&quot;1233&quot;&gt;
&lt;p data-start=&quot;1139&quot; data-end=&quot;1233&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;Review and interpret analysis outputs, ensuring accuracy, quality, and regulatory compliance&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot; data-start=&quot;1234&quot; data-end=&quot;1342&quot;&gt;
&lt;p data-start=&quot;1236&quot; data-end=&quot;1342&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;Collaborate with cross-functional teams including Clinical, Programming, Data Management, and Regulatory&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot; data-start=&quot;1343&quot; data-end=&quot;1414&quot;&gt;
&lt;p data-start=&quot;1345&quot; data-end=&quot;1414&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;Provide guidance and oversight to statistical programmers as needed&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot; data-start=&quot;1415&quot; data-end=&quot;1528&quot;&gt;
&lt;p data-start=&quot;1417&quot; data-end=&quot;1528&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;Communicate statistical concepts, results, and risks clearly to both technical and non-technical stakeholders&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot; data-start=&quot;1529&quot; data-end=&quot;1606&quot;&gt;
&lt;p data-start=&quot;1531&quot; data-end=&quot;1606&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;Ensure adherence to regulatory standards (FDA, ICH, GCP) and company SOPs&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 style=&quot;line-height: 1.2;&quot; data-start=&quot;1608&quot; data-end=&quot;1637&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;Required Qualifications&lt;/span&gt;&lt;/h3&gt;
